//! SSO (Singapore Statutes Online) deep-link URL builder.
//!
//! Builds provision-level URLs of the form:
//!   `https://sso.agc.gov.sg/Act/{ACT_CODE}?ProvIds=pr{section}-`
//!
//! The act-title→code mapping is loaded at runtime from `SSO_ACT_INDEX_PATH`
//! (default `data/sso_act_index.json`, generated by
//! `scripts/build_sso_act_index.py`). Without it no SSO deep links are built.

use crate::models::schemas::LegislationCitation;
use std::collections::HashMap;
use std::sync::LazyLock;

const SSO_BASE: &str = "https://sso.agc.gov.sg/Act";

static ACT_INDEX: LazyLock<HashMap<String, String>> = LazyLock::new(|| {
    let path = std::env::var("SSO_ACT_INDEX_PATH")
        .unwrap_or_else(|_| "data/sso_act_index.json".to_string());
    match std::fs::read_to_string(&path) {
        Ok(s) => serde_json::from_str(&s).unwrap_or_default(),
        Err(e) => {
            tracing::warn!(path = %path, error = %e, "SSO act index not loaded; no SSO deep links");
            HashMap::new()
        }
    }
});

/// True when the act index was loaded; tests that need act codes skip otherwise.
pub fn index_available() -> bool {
    !ACT_INDEX.is_empty()
}

/// Acts whose Qdrant `source_file` uses an old title that differs from the
/// current SSO title.  Maps old → current so `act_code()` can resolve them.
static RENAMED_ACTS: LazyLock<HashMap<&str, &str>> = LazyLock::new(|| {
    HashMap::from([(
        "Tobacco (Control of Advertisements and Sale) Act 1993",
        "Tobacco and Vaporisers Control Act 1993",
    )])
});

/// Look up the SSO act code for a given act title.
///
/// Tries the index directly, then falls back to `RENAMED_ACTS` aliases.
pub fn act_code(act_name: &str) -> Option<&str> {
    if let Some(code) = ACT_INDEX.get(act_name) {
        return Some(code.as_str());
    }
    let canonical = RENAMED_ACTS.get(act_name)?;
    ACT_INDEX.get(*canonical).map(|s| s.as_str())
}

/// Build the SSO provision ID string for a section number.
///
/// `"13A"` → `"pr13A-"`, `"5"` → `"pr5-"`
/// Case is preserved because SSO URLs are case-sensitive.
pub fn provision_id(section: &str) -> String {
    format!("pr{}-", section)
}

/// Digits of a schedule section id: `schedule1` and `schedule1_part2` → `Some("1")`;
/// an unnumbered schedule (`schedule`, `schedule_part1`) → `Some("")`; anything else
/// (`19`, `legislative_history`, `part_1_2`) → `None`.
fn schedule_digits(section: &str) -> Option<&str> {
    let rest = section.strip_prefix("schedule")?;
    let digits_len = rest.chars().take_while(|c| c.is_ascii_digit()).count();
    let (digits, tail) = rest.split_at(digits_len);
    (tail.is_empty() || tail.starts_with('_')).then_some(digits)
}

/// The SSO anchor for a section id and the canonical section it stands for:
/// numbered provisions get `pr19-`; schedules get `Sc1-` (`Sc-` when the Act has a
/// single unnumbered schedule), whatever part of the schedule the id names, so
/// every part of a schedule maps to one link. Appendices, tables of comparison and
/// the legislative history have no anchor.
pub fn provision_ref(section: &str) -> Option<(String, String)> {
    if section.chars().next().is_some_and(|c| c.is_ascii_digit()) {
        return Some((section.to_string(), provision_id(section)));
    }
    let digits = schedule_digits(section)?;
    Some((format!("schedule{digits}"), format!("Sc{digits}-")))
}

/// Build a full SSO deep-link URL for a specific act + section.
///
/// Returns `None` if the act is not in the index.
pub fn act_section_url(act_name: &str, section: &str) -> Option<String> {
    let code = act_code(act_name)?;
    let (_, anchor) = provision_ref(section)?;
    Some(format!("{}/{}?ProvIds={}", SSO_BASE, code, anchor))
}

/// Build a provision-level SSO URL from a document-level `sso_url` payload field.
///
/// Act URLs are bare (`…/Act/ITA1947`) and get `?ProvIds=pr13-`. Subsidiary
/// legislation URLs already carry a query (`…/SL/CONS1963-S23-2023?DocDate=20260130`),
/// so the provision id is joined with `&` instead of a second `?`.
pub fn section_url_from_sso_base(base: &str, section: &str) -> String {
    let base = base.trim();
    if base.is_empty() {
        return String::new();
    }
    let base = base.trim_end_matches('/');
    if base.contains("ProvIds=") {
        return base.to_string();
    }
    let Some((_, anchor)) = provision_ref(section) else {
        return String::new();
    };
    let sep = if base.contains('?') { '&' } else { '?' };
    format!("{}{}ProvIds={}", base, sep, anchor)
}

/// True when `section` has an SSO anchor: numbered provisions (`19`, `13A`) and
/// schedules (`schedule3`). Appendices and the legislative history do not, so no
/// deep link is built for them.
pub fn is_linkable_provision(section: &str) -> bool {
    provision_ref(section).is_some()
}

/// Human document name for a subsidiary-legislation `source_file`: drops the
/// extension and the trailing enactment reference, e.g.
/// `Public Service (Disciplinary Proceedings) Regulations 2023 [S 23_2023].md`
/// becomes `Public Service (Disciplinary Proceedings) Regulations 2023`.
pub fn sl_document_name(source_file: &str) -> String {
    let name = source_file
        .trim()
        .trim_end_matches(".pdf")
        .trim_end_matches(".md")
        .trim();
    match name.rfind(" [") {
        Some(i) if name.ends_with(']') => name[..i].trim().to_string(),
        _ => name.to_string(),
    }
}

/// How far (bytes) a section reference may sit from the Act title it belongs to.
const NAME_WINDOW: usize = 160;

static SECTION_REF: LazyLock<regex::Regex> = LazyLock::new(|| {
    // "section 19", "s 19", "s. 19", "ss 19 and 20" (first number), "s19(5)".
    regex::Regex::new(r"(?i)(?:^|[^\w'\u{2019}])(?:sections?|ss?\.?)\s*(\d+(?-i:[A-Z]{0,3}))(?:\(\w+\))*")
        .expect("valid section regex")
});

/// Build citations for Acts the answer names in full ("Companies Act 1967, s 19(5)")
/// whose sections were never retrieved by a search, so the model's own references
/// still get an SSO link. Each section number is attached to the nearest Act title
/// within `NAME_WINDOW`; the client then applies the same matching rules it uses
/// for retrieved citations.
pub fn citations_from_text(text: &str) -> Vec<LegislationCitation> {
    // Occurrences of every indexed title; a title inside a longer one
    // ("Companies Act 1967" in "Finance Companies Act 1967") is dropped.
    let mut hits: Vec<(usize, usize, &str)> = Vec::new();
    for name in ACT_INDEX.keys() {
        for (pos, _) in text.match_indices(name.as_str()) {
            hits.push((pos, pos + name.len(), name.as_str()));
        }
    }
    if hits.is_empty() {
        return Vec::new();
    }
    let all = hits.clone();
    hits.retain(|&(s, e, _)| !all.iter().any(|&(s2, e2, _)| s2 <= s && e <= e2 && (e2 - s2) > (e - s)));

    let mut seen = std::collections::HashSet::new();
    let mut out = Vec::new();
    for caps in SECTION_REF.captures_iter(text) {
        let num = caps.get(1).expect("group 1");
        let (start, end) = (num.start(), num.end());
        let nearest = hits
            .iter()
            .map(|&(s, e, name)| {
                let dist = if e <= start { start - e } else if s >= end { s - end } else { 0 };
                (dist, name)
            })
            .filter(|&(d, _)| d <= NAME_WINDOW)
            .min_by_key(|&(d, _)| d);
        let Some((_, act_name)) = nearest else { continue };
        let section = num.as_str();
        if !seen.insert((act_name, section.to_string())) {
            continue;
        }
        if let Some(url) = act_section_url(act_name, section) {
            out.push(LegislationCitation {
                act_name: act_name.to_string(),
                section: section.to_string(),
                label: format!("s.{}", section),
                url,
                doc_type: "act".to_string(),
            });
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Assertions below need `data/sso_act_index.json`, which is not vendored.
    fn have_index() -> bool {
        if ACT_INDEX.is_empty() {
            eprintln!("skipping: data/sso_act_index.json not present");
            return false;
        }
        true
    }

    #[test]
    fn citations_from_text_links_acts_named_in_the_answer() {
        if !have_index() {
            return;
        }
        let c = citations_from_text(
            "per Companies Act 1967, s 19(5); and see s 215 of the Companies Act 1967. Lina's 19 vans.",
        );
        let secs: Vec<_> = c.iter().map(|x| (x.act_name.as_str(), x.section.as_str())).collect();
        assert_eq!(secs, vec![("Companies Act 1967", "19"), ("Companies Act 1967", "215")]);
        assert_eq!(c[0].url, "https://sso.agc.gov.sg/Act/CoA1967?ProvIds=pr19-");
    }

    #[test]
    fn citations_from_text_ignores_far_sections_and_longer_titles() {
        if !have_index() {
            return;
        }
        assert!(citations_from_text("Section 5 applies.").is_empty());
        let c = citations_from_text("Finance Companies Act 1967, s 4");
        assert_eq!(c.len(), 1);
        assert_eq!(c[0].act_name, "Finance Companies Act 1967");
        let far = format!("Road Traffic Act 1961.{} s 4", " ".repeat(400));
        assert!(citations_from_text(&far).is_empty());
    }

    #[test]
    fn test_provision_id() {
        assert_eq!(provision_id("5"), "pr5-");
        assert_eq!(provision_id("13"), "pr13-");
        assert_eq!(provision_id("13A"), "pr13A-");
        assert_eq!(provision_id("48E"), "pr48E-");
    }

    #[test]
    fn test_section_url_from_sso_base() {
        assert_eq!(
            section_url_from_sso_base("https://sso.agc.gov.sg/Act/MTERA1972", "8"),
            "https://sso.agc.gov.sg/Act/MTERA1972?ProvIds=pr8-"
        );
        assert_eq!(
            section_url_from_sso_base("https://sso.agc.gov.sg/Act/MTERA1972?ProvIds=pr8-", "8"),
            "https://sso.agc.gov.sg/Act/MTERA1972?ProvIds=pr8-"
        );
    }

    #[test]
    fn sl_urls_join_the_provision_with_an_ampersand() {
        assert_eq!(
            section_url_from_sso_base(
                "https://sso.agc.gov.sg/SL/CONS1963-S23-2023?DocDate=20260130",
                "19"
            ),
            "https://sso.agc.gov.sg/SL/CONS1963-S23-2023?DocDate=20260130&ProvIds=pr19-"
        );
    }

    #[test]
    fn numbered_provisions_and_schedules_are_linkable() {
        assert!(is_linkable_provision("19"));
        assert!(is_linkable_provision("13A"));
        assert!(is_linkable_provision("2D"));
        assert!(is_linkable_provision("schedule3"));
        assert!(!is_linkable_provision("legislative_history"));
        assert!(!is_linkable_provision("abbreviations"));
        assert!(!is_linkable_provision("part_1_2"));
        assert!(!is_linkable_provision("scheduled"));
        assert!(!is_linkable_provision(""));
    }

    #[test]
    fn schedules_map_to_one_sc_anchor() {
        if !have_index() {
            return;
        }
        assert_eq!(provision_ref("schedule1"), Some(("schedule1".into(), "Sc1-".into())));
        assert_eq!(provision_ref("schedule1_part2"), Some(("schedule1".into(), "Sc1-".into())));
        assert_eq!(provision_ref("schedule12_table1b"), Some(("schedule12".into(), "Sc12-".into())));
        assert_eq!(provision_ref("schedule"), Some(("schedule".into(), "Sc-".into())));
        assert_eq!(provision_ref("schedule_part3"), Some(("schedule".into(), "Sc-".into())));
        assert_eq!(
            section_url_from_sso_base(
                "https://sso.agc.gov.sg/SL/CoA1967-S833-2015?DocDate=20241206",
                "schedule1"
            ),
            "https://sso.agc.gov.sg/SL/CoA1967-S833-2015?DocDate=20241206&ProvIds=Sc1-"
        );
        assert_eq!(
            act_section_url("Companies Act 1967", "schedule2"),
            Some("https://sso.agc.gov.sg/Act/CoA1967?ProvIds=Sc2-".to_string())
        );
        assert_eq!(section_url_from_sso_base("https://sso.agc.gov.sg/Act/CoA1967", "abbreviations"), "");
    }

    #[test]
    fn sl_document_name_drops_extension_and_enactment_reference() {
        assert_eq!(
            sl_document_name("Public Service (Disciplinary Proceedings) Regulations 2023 [S 23_2023].md"),
            "Public Service (Disciplinary Proceedings) Regulations 2023"
        );
        assert_eq!(
            sl_document_name("Protected Places (Consolidation) Order [Cap. 137B, OR 2].md"),
            "Protected Places (Consolidation) Order"
        );
        assert_eq!(sl_document_name("Some Rules.pdf"), "Some Rules");
    }

    #[test]
    fn test_act_code_lookup() {
        if !have_index() {
            return;
        }
        assert_eq!(act_code("Accountants Act 2004"), Some("AA2004"));
        assert_eq!(act_code("Computer Misuse Act 1993"), Some("CMA1993"));
        assert_eq!(act_code("Income Tax Act 1947"), Some("ITA1947"));
        assert_eq!(act_code("Nonexistent Act 9999"), None);
    }

    #[test]
    fn test_renamed_act_alias() {
        if !have_index() {
            return;
        }
        assert_eq!(
            act_code("Tobacco (Control of Advertisements and Sale) Act 1993"),
            Some("TVCA1993")
        );
        assert_eq!(
            act_code("Tobacco and Vaporisers Control Act 1993"),
            Some("TVCA1993")
        );
    }

    #[test]
    fn test_act_section_url() {
        if !have_index() {
            return;
        }
        assert_eq!(
            act_section_url("Accountants Act 2004", "5"),
            Some("https://sso.agc.gov.sg/Act/AA2004?ProvIds=pr5-".to_string())
        );
        assert_eq!(
            act_section_url("Computer Misuse Act 1993", "17"),
            Some("https://sso.agc.gov.sg/Act/CMA1993?ProvIds=pr17-".to_string())
        );
        assert_eq!(
            act_section_url("Income Tax Act 1947", "13"),
            Some("https://sso.agc.gov.sg/Act/ITA1947?ProvIds=pr13-".to_string())
        );
        assert_eq!(
            act_section_url("Income Tax Act 1947", "13A"),
            Some("https://sso.agc.gov.sg/Act/ITA1947?ProvIds=pr13A-".to_string())
        );
        assert_eq!(act_section_url("Nonexistent Act 9999", "1"), None);
    }
}
